import 'package:flutter/material.dart';import '../../models/club.dart';import '../../models/app_models.dart';import '../community/community_screen.dart';
class TeamScreen extends StatefulWidget{final Club club;const TeamScreen({super.key,required this.club});@override State<TeamScreen> createState()=>_S();}class _S extends State<TeamScreen>{int tab=0;@override Widget build(BuildContext c){final labels=['סקירה','סגל','נתונים','מועדון','היציע'];return SafeArea(child:Column(children:[Padding(padding:const EdgeInsets.all(18),child:Container(width:double.infinity,padding:const EdgeInsets.all(22),decoration:BoxDecoration(borderRadius:BorderRadius.circular(28),color:widget.club.accent.withValues(alpha:.15),border:Border.all(color:widget.club.accent.withValues(alpha:.3))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.club.name,style:const TextStyle(fontSize:30,fontWeight:FontWeight.w900)),const Text('הקבוצה שלי • חיים את הקבוצה.',style:TextStyle(color:Colors.white60))]))),SizedBox(height:44,child:ListView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.symmetric(horizontal:12),children:List.generate(labels.length,(i)=>Padding(padding:const EdgeInsets.symmetric(horizontal:4),child:ChoiceChip(label:Text(labels[i]),selected:tab==i,onSelected:(_)=>setState(()=>tab=i))))),),Expanded(child:_body())]));}Widget _body(){if(tab==1)return ListView(padding:const EdgeInsets.all(18),children:demoPlayers().map((p)=>Card(child:ListTile(leading:CircleAvatar(backgroundColor:widget.club.accent,child:Text('${p.number}')),title:Text(p.name),subtitle:Text('${p.position} • ${p.apps} הופעות'),trailing:Text('${p.goals} ⚽')))).toList());if(tab==4)return CommunityScreen(club:widget.club,embedded:true);final data=tab==0?['מיקום בליגה  •  3','נקודות  •  11','מאזן  •  3 ניצחונות, 2 תיקו','כושר אחרון  •  נ–נ–ת–נ–ת']:tab==2?['שערי זכות  •  10','שערי חובה  •  5','משחקים ללא ספיגה  •  2','מלך השערים  •  4']:['אצטדיון  •  יעודכן ממערכת הניהול','תארים  •  ארכיון המועדון','היסטוריה  •  ציר זמן','שירי אוהדים  •  מאגר היציע'];return ListView(padding:const EdgeInsets.all(18),children:data.map((x)=>Card(child:Padding(padding:const EdgeInsets.all(20),child:Text(x,style:const TextStyle(fontSize:17,fontWeight:FontWeight.w700))))).toList());}}
